package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.nio.charset.Charset;
import java.nio.charset.CharsetEncoder;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Jsoup;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Document_title_TriageGen1Test {

    private Document emptyDoc;
    private Document docWithTitle;
    private Document docWithWhitespaceTitle;
    private Document docWithoutTitle;

    @Before
    public void setUp() {
        emptyDoc = Jsoup.parse("");
        docWithTitle = Jsoup.parse("<html><head><title>Test Title</title></head></html>");
        docWithWhitespaceTitle = Jsoup.parse("<html><head><title>    Whitespace Title    </title></head></html>");
        docWithoutTitle = Jsoup.parse("<html><head></head><body></body></html>");
    }

    @Test
    public void testTitleWithValidTitle() {
        assertEquals("Test Title", docWithTitle.title());
    }

    @Test
    public void testTitleWithWhitespaceTitle() {
        assertEquals("Whitespace Title", docWithWhitespaceTitle.title());
    }

    @Test
    public void testTitleWithNoTitle() {
        assertEquals("", docWithoutTitle.title());
    }

    @Test
    public void testTitleWithEmptyDocument() {
        assertEquals("", emptyDoc.title());
    }

    @Test
    public void testTitleWithMultipleTitles() {
        Document multipleTitlesDoc = Jsoup.parse("<html><head><title>First Title</title><title>Second Title</title></head></html>");
        assertEquals("First Title", multipleTitlesDoc.title());
    }

    @Test
    public void testTitleWithNullDocument() {
        Document nullDoc = null;
        try {
            nullDoc.title();
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected exception
        }
    }
}
